examples.code:
raw = '42x'
try:
    number = int(raw)
except ValueError:
    print('Enter a whole number')

try:
    amount = int('many')
except ValueError as error:
    print(type(error).__name__)
    print('Invalid amount')

for raw in ['8', 'bad', '5']:
    try:
        print(int(raw) * 2)
    except ValueError:
        print('Skipped invalid input')

def read_score(text):
    try:
        return int(text)
    except ValueError:
        return 0
print(read_score('7'))
print(read_score('unknown'))

try:
    print([1, 2][5])
except IndexError:
    print('No item at that position')
